function prefixStencilsFloorTicket(readings: number[], k: number): number {
  const a=readings; let out:number[]=[];
  const sums=[0];for(const x of a)sums.push(sums.at(-1)!+x);for(let i=0;i<a.length;i++)out.push(sums[i+1]-sums[Math.max(0,i-k+1)]);
  return out.length?Math.min(...out):0;
}


python
def prefixStencilsFloorTicket(readings, k):
    a=readings
    out=[]
    sums=[0]
    for x in a: sums.append(sums[-1]+x)
    for i in range(len(a)): out.append(sums[i+1]-sums[max(0,i-k+1)])
    return min(out,default=0)


java
class Solution {
  public int prefixStencilsFloorTicket(int[] readings, int k) {
    int[] a=readings; List<Integer> out=new ArrayList<>();
    {int[]sums=new int[a.length+1];for(int i=0;i<a.length;i++)sums[i+1]=sums[i]+a[i];for(int i=0;i<a.length;i++)out.add(sums[i+1]-sums[Math.max(0,i-k+1)]);}
    int answer=out.isEmpty()?0:out.get(0);for(int x:out)answer=Math.min(answer,x);return answer;
  }
}
